package com.ethk3.novaonepro.strategyv2;
import java.io.*;import java.lang.reflect.*;import java.util.*;
public final class R26ResidualDiagnosticsTest {
 static void check(boolean x,String why){if(!x)throw new AssertionError(why);}
 static Object get(ResidualFamilyR26 m,String name)throws Exception{Field f=ResidualFamilyR26.class.getDeclaredField(name);f.setAccessible(true);return f.get(m);}
 static byte[] save(ResidualFamilyR26 m)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
 static ResidualFamilyR26 restore(byte[] bytes)throws Exception{ResidualFamilyR26 m=new ResidualFamilyR26();m.read(new DataInputStream(new ByteArrayInputStream(bytes)));return m;}
 static int[] draw(Random r){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int j=r.nextInt(i+1),v=d[i];d[i]=d[j];d[j]=v;}return d;}
 static double loss(ResidualFamilyR26 m,int[] target)throws Exception{Method method=ResidualFamilyR26.class.getDeclaredMethod("scores");method.setAccessible(true);double[][] scores=(double[][])method.invoke(m);int[] zero=target.clone();for(int i=0;i<10;i++)zero[i]--;return ExactPermutationR26.nll(scores,zero,ExactPermutationR26.infer(scores,null));}
 static void interrupt(byte[] bytes,int[] target)throws Exception{for(int budget:new int[]{1,20,100}){ResidualFamilyR26 m=restore(bytes);ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,budget,()->false));boolean yielded=false;try{m.update(target);}catch(BudgetTokenSU1.Yield expected){yielded=true;}finally{ExecutionBudgetR26.leave();}check(yielded&&Arrays.equals(bytes,save(m))&&m.lastTrainingStep()==null,"interrupted phased update partially committed");}}
 public static void main(String[] args)throws Exception{
  ResidualFamilyR26 m=new ResidualFamilyR26();Random random=new Random(2622);byte[] bootstrap=null;
  for(int i=0;i<142;i++){m.update(draw(random));TrainingDiagnosticsR26.Step s=m.lastTrainingStep();check(s!=null&&s.update==i+1,"missing actual update clock");if(i<128){TrainingDiagnosticsR26.Step p=((FamilyF01KernelR26)get(m,"parent")).lastTrainingStep();check(p!=null&&s.lossBefore==p.lossBefore&&s.lossAfter==p.lossAfter&&s.gradientNorm==p.gradientNorm&&s.parameterDeltaNorm==p.parameterDeltaNorm&&s.objective.startsWith("F22_PARENT_BOOTSTRAP"),"bootstrap diagnostics differ from actual parent update");}else check(s.objective.contains("PARENT_WEIGHTS_FROZEN"),"residual phase mislabeled");if(i==19)bootstrap=save(m);}
  byte[] before=save(m);String frozen=(String)get(m,"frozenParent");check(frozen.equals(((FamilyF01KernelR26)get(m,"parent")).parameterHash()),"frozen parent differs");double[][] residual=(double[][])get(m,"residual");double[] gate=(double[])get(m,"gate");int[] target=draw(random);double[] finite=new double[22];int coordinates=0;
  for(int k=0;k<22;k++){double old,plus,minus;int row=(k*19)%100,j=k%3;if(k<20){old=residual[row][j];residual[row][j]=old+1e-5;plus=loss(m,target);residual[row][j]=old-1e-5;minus=loss(m,target);residual[row][j]=old;}else{j=k-20;old=gate[j];gate[j]=old+1e-5;plus=loss(m,target);gate[j]=old-1e-5;minus=loss(m,target);gate[j]=old;}finite[k]=(plus-minus)/2e-5;coordinates++;}
  double beforeLoss=loss(m,target);m.update(target);TrainingDiagnosticsR26.Step step=m.lastTrainingStep();double[][] nextResidual=(double[][])get(m,"residual");double[] nextGate=(double[])get(m,"gate");ResidualFamilyR26 fixed=restore(before);double[][] fixedResidual=(double[][])get(fixed,"residual");double[] fixedGate=(double[])get(fixed,"gate");for(int i=0;i<100;i++)System.arraycopy(nextResidual[i],0,fixedResidual[i],0,3);System.arraycopy(nextGate,0,fixedGate,0,2);check(Math.abs(step.lossBefore-beforeLoss)<1e-12&&Math.abs(step.lossAfter-loss(fixed,target))<1e-12,"after loss advanced pre-label context");double grad2=0,delta2=0,maxError=0;for(int i=0;i<100;i++)for(int j=0;j<3;j++){double d=nextResidual[i][j]-residual[i][j];delta2+=d*d;grad2+=(d/.02)*(d/.02);}for(int j=0;j<2;j++){double d=nextGate[j]-gate[j];delta2+=d*d;grad2+=(d/.01)*(d/.01);}check(Math.abs(step.gradientNorm-Math.sqrt(grad2))<1e-12&&step.parameterDeltaNorm==Math.sqrt(delta2),"actual gradient and parameter coordinates differ");
  for(int k=0;k<22;k++){double actual=k<20?(residual[(k*19)%100][k%3]-nextResidual[(k*19)%100][k%3])/.02:(gate[k-20]-nextGate[k-20])/.01;maxError=Math.max(maxError,Math.abs(actual-finite[k]));check(Math.abs(actual-finite[k])<1e-7,"joint residual or gate derivative differs");}
  check(frozen.equals(((FamilyF01KernelR26)get(m,"parent")).parameterHash()),"residual updated frozen parent weights");ResidualFamilyR26 alternative=restore(before);alternative.update(draw(random));check(step.inputHash.equals(alternative.lastTrainingStep().inputHash),"target leaked into input hash");ResidualFamilyR26 copy=restore(save(m));target=draw(random);m.update(target);copy.update(target);check(Arrays.equals(save(m),save(copy)),"restored next phased update differs");long t=m.completedTrainingUpdates();m.resetTemporalContext();check(t==m.completedTrainingUpdates()&&m.lastTrainingStep()==null&&frozen.equals(((FamilyF01KernelR26)get(m,"parent")).parameterHash()),"gap reset learned state or bootstrap phase");copy=restore(save(m));target=draw(random);m.update(target);copy.update(target);check(Arrays.equals(save(m),save(copy)),"gap restore differs");
  byte[] good=save(m);for(int kind=0;kind<3;kind++){byte[] bad=good.clone();if(kind==0)bad=Arrays.copyOf(bad,bad.length-1);if(kind==1)bad[14]='x';if(kind==2)bad[0]=0;try{m.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("bad state accepted");}catch(IOException expected){}check(Arrays.equals(good,save(m)),"bad read changed full retained state");}interrupt(bootstrap,target);interrupt(good,target);
  if(args.length>0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0]),good);
  System.out.println("R26_RESIDUAL_DIAGNOSTICS_PASS|bootstrapAndResidualMeasured=true|finiteDifferenceCoordinates="+coordinates+"|maximumGradientError="+maxError+"|parentWeightsFrozen=true|counterSurvivesGap=true|fixedPreLabelContext=true|restoreAndBothPhaseCancelAtomic=true|scope=SYNTHETIC_NOT_NATURAL_QUALITY");
 }
}
